    public static void install(ArmyStrengthsFamilies.Registry registry,ArmyStrengthsPipeline pipeline,ExactRef actualJavaBundleSource) {
        add(registry,Key.REGIMENT_REPLENISHMENT,FirstRecordReplenishment.class,(node,row)->decodeFirst(node),ArmyStrengthsRefill::encodeFirst,actualJavaBundleSource);
        add(registry,Key.REGIMENT_REPLENISHMENT_RECORDS_V1,FullDataRecords.class,(node,row)->new FullDataRecords(array(node,LandContextCodec::decodeData)),value->{ArrayNode out=empty().arrayNode();value.values().forEach(data->out.add(LandContextCodec.encodeData(data)));return out;},actualJavaBundleSource);
        add(registry,Key.FIXED_CHUNK0_PREPARATION_INPUTS_V1,FixedPreparation.class,(node,row)->new FixedPreparation(decodePreparation(normalizePreparation(node,row,false),false)),value->encodePreparation(value.value(),false),actualJavaBundleSource);
        add(registry,Key.CURRENT_PROVINCE_BESIEGING_CONTRIBUTORS_V1,Besieging.class,(node,row)->decodeBesieging(node),ArmyStrengthsRefill::encodeBesieging,actualJavaBundleSource);
        add(registry,Key.CURRENT_LAND_SUPPLY_RATE_INPUTS_V1,LandRateInputs.class,(node,row)->LandContextCodec.decodeRate(node),LandContextCodec::encodeRate,actualJavaBundleSource);
        add(registry,Key.SCOPED_ORDERED_REFILL_INPUTS_V1,ScopedOrdered.class,(node,row)->decodeScoped(node),ArmyStrengthsRefill::encodeScoped,actualJavaBundleSource);
        add(registry,Key.ORDERED_BESIEGING_REFILL_INPUTS_V1,OrderedBesieging.class,(node,row)->decodeNativeOrderedBesieging(node),ArmyStrengthsRefill::encodeOrderedBesieging,actualJavaBundleSource);
        add(registry,Key.ORDERED_BESIEGING_FIXED_CHUNK0_PREPARATION_INPUTS_V1,OrderedBesiegingPreparation.class,(node,row)->new OrderedBesiegingPreparation(decodePreparation(normalizePreparation(node,row,true),true)),value->encodePreparation(value.value(),true),actualJavaBundleSource);
        add(registry,Key.NEXT_ROUTE_REPLENISHMENT_POSITION_INPUTS_V1,NextPositionInputs.class,(node,row)->decodeNextPosition(node,row.army().value()),ArmyStrengthsRefill::encodeNextPosition,actualJavaBundleSource);
        ArmyStrengthsRefillProjections.install(pipeline,actualJavaBundleSource);
    }
    private static <T> void add(ArmyStrengthsFamilies.Registry registry,Key key,Class<T> type,BiFunction<JsonNode,ArmyStrengths.Core,T> decoder,Function<T,JsonNode> encoder,ExactRef source) {
        registry.register(key,type,(input,row)->{
            if(input instanceof Missing<RawJson>)return key.defaultNullWhenMissing()?new NullValue<>():new Missing<>();
            if(input instanceof NullValue<RawJson>){require(key!=Key.REGIMENT_REPLENISHMENT&&key!=Key.REGIMENT_REPLENISHMENT_RECORDS_V1,"present refill records must be arrays, not null");return new NullValue<>();}
            return new Present<>(decoder.apply(parseValue(((Present<RawJson>)input).value()),row.core()));
        },field->field instanceof Present<T> value?raw(encoder.apply(value.value())):raw(NullNode.getInstance()),
          field->publicFamily(key,field instanceof Present<T> value?raw(encoder.apply(value.value())):raw(NullNode.getInstance())),source);
    }
    static RawJson raw(JsonNode node){return new RawJson(bytes(node));}
    static JsonNode parseValue(RawJson json){return ArmyStrengthsCodec.parseValue(json);}
    static RawJson publicFamily(Key key,RawJson nativeJson){
        List<String> paths=new ArrayList<>();switch(key){
            case REGIMENT_REPLENISHMENT->paths.add("/*/chunks/*/persistent_monthly_replenishment_fraction_raw");
            case REGIMENT_REPLENISHMENT_RECORDS_V1->{paths.add("/*/records/*/persistent_monthly_replenishment_fraction_raw");paths.add("/*/records/*/persistent_prepared_replenishment_fraction_raw");}
            case FIXED_CHUNK0_PREPARATION_INPUTS_V1,ORDERED_BESIEGING_FIXED_CHUNK0_PREPARATION_INPUTS_V1->paths.add("/persistent_regiments/*/fresh_fraction_raw");
            case CURRENT_PROVINCE_BESIEGING_CONTRIBUTORS_V1->{paths.add("/assault_context/casualty_percentage_raw");paths.add("/occurrences/*/regiments/*/replenishment_records_v1/records/*/persistent_monthly_replenishment_fraction_raw");paths.add("/occurrences/*/regiments/*/replenishment_records_v1/records/*/persistent_prepared_replenishment_fraction_raw");}
            case CURRENT_LAND_SUPPLY_RATE_INPUTS_V1->{for(String field:List.of("province_component_raw","commander_modifier_1a9_raw","loaded_excess_slope_raw","loaded_min_loss_raw","loaded_max_loss_raw","loaded_divisor_floor_raw"))paths.add("/"+field);}
            case SCOPED_ORDERED_REFILL_INPUTS_V1,ORDERED_BESIEGING_REFILL_INPUTS_V1->paths.add("/persistent_regiments/*/prepared_fraction_raw");
            case NEXT_ROUTE_REPLENISHMENT_POSITION_INPUTS_V1->{ }
            default->throw new IllegalArgumentException("not a REFILL-owned family: "+key);
        }
        return ArmyStrengthsPublicNumbers.encode(nativeJson,paths.stream().map(path->new ArmyStrengthsPublicNumbers.Rule(path,ArmyStrengthsPublicNumbers.Domain.SIGNED_64)).toList());
    }
    public static JsonNode normalizeData(JsonNode node){return LandContextCodec.encodeData(LandContextCodec.decodeData(node));}
    static <E extends Enum<E>> E enumeration(JsonNode node,Class<E> type){return Enum.valueOf(type,text(node).toUpperCase(java.util.Locale.ROOT));}
    static String wire(Enum<?> value){return value.name().toLowerCase(java.util.Locale.ROOT);}
    static void put(ObjectNode node,String key,Number value){if(value==null)node.putNull(key);else node.put(key,value.longValue());}
    static void put(ObjectNode node,String key,Boolean value){if(value==null)node.putNull(key);else node.put(key,value);}
    static void put(ObjectNode node,String key,String value){if(value==null)node.putNull(key);else node.put(key,value);}
    public static FirstRecordReplenishment decodeFirst(JsonNode node){
        List<FirstRecord> records=new ArrayList<>();for(JsonNode raw:normalizeFirstRecords(node)){ObjectNode row=object(raw);List<FirstChunk> chunks=new ArrayList<>();for(JsonNode item:row.get("chunks"))chunks.add(new FirstChunk(i32(item.get("persistent_regiment_id")),i32(item.get("chunk_index")),i32(item.get("current_soldiers")),i32(item.get("maximum_soldiers")),i32(item.get("state_raw")),bool(item.get("native_can_replenish")),bool(item.get("native_chunk_can_replenish")),i64(item.get("persistent_monthly_replenishment_fraction_raw"))));records.add(new FirstRecord(i32(row.get("army_regiment_id")),ni(row,"native_data_record_count"),enumeration(row.get("status"),Coverage.class),reason(row,"unavailable_reason",false),chunks));}return new FirstRecordReplenishment(records);
    }
    public static JsonNode encodeFirst(FirstRecordReplenishment value){ArrayNode rows=empty().arrayNode();for(FirstRecord record:value.values()){
        ObjectNode row=rows.addObject().put("army_regiment_id",record.armyRegimentId()).put("source","native_first_record").put("status",wire(record.status()));put(row,"native_data_record_count",record.nativeDataRecordCount());put(row,"unavailable_reason",record.unavailableReason());ArrayNode chunks=row.putArray("chunks");for(FirstChunk chunk:record.chunks())chunks.addObject().put("persistent_regiment_id",chunk.persistentRegimentId()).put("chunk_index",chunk.chunkIndex()).put("current_soldiers",chunk.currentSoldiers()).put("maximum_soldiers",chunk.maximumSoldiers()).put("state_raw",chunk.stateRaw()).put("native_can_replenish",chunk.nativeCanReplenish()).put("native_chunk_can_replenish",chunk.nativeChunkCanReplenish()).put("persistent_monthly_replenishment_fraction_raw",chunk.monthlyFractionRaw()).put("persistent_monthly_replenishment_fraction_scale",100000);
    }return rows;}
    static Preparation decodePreparation(ObjectNode row,boolean b){
        List<PreparationPersistent> values=new ArrayList<>();for(JsonNode raw:row.get("persistent_regiments")){ObjectNode p=object(raw);values.add(new PreparationPersistent(i32(p.get("persistent_regiment_id")),enumeration(p.get("status"),Coverage.class),bool(p.get("ready")),reason(p,"unavailable_reason",false),ni(p,"containing_guard_138_raw"),nu(p,"containing_definition_magic_38"),nb(p,"native_fixed_chunk0_can_replenish"),nl(p,"fresh_fraction_raw")));}
        return new Preparation(enumeration(row.get("status"),Coverage.class),bool(row.get("ready")),reason(row,"unavailable_reason",false),i32(row.get("subject_army_id")),i32(row.get("subject_carmy_id")),bool(row.get(b?"target_persistent_ids_complete":"referenced_persistent_ids_complete")),values,b?i32(row.get("province_id")):null,b?enumeration(row.get("source_scope_status"),Coverage.class):null);
    }
    static JsonNode encodePreparation(Preparation value,boolean b){
        ObjectNode row=empty().put("source",b?"native_ordered_besieging_fixed_chunk0_preparation_inputs":"native_scoped_fixed_chunk0_preparation_inputs").put("entry_kind","current_frozen_context_preparation").put("status",wire(value.status())).put("ready",value.ready()).put("subject_army_id",value.subjectArmyId()).put("subject_carmy_id",value.subjectCarmyId()).put(b?"target_persistent_ids_complete":"referenced_persistent_ids_complete",value.complete());put(row,"unavailable_reason",value.unavailableReason());
        if(b){row.put("scope_kind","actual_ordered_besieging_target_physical_union");put(row,"province_id",value.provinceId());row.put("source_scope_status",wire(value.sourceScopeStatus()));}
        ArrayNode persistents=row.putArray("persistent_regiments");for(PreparationPersistent p:value.persistentRegiments()){ObjectNode item=persistents.addObject().put("persistent_regiment_id",p.persistentRegimentId()).put("fixed_chunk_index",0).put("status",wire(p.status())).put("ready",p.ready()).put("fraction_scale",100000);put(item,"unavailable_reason",p.unavailableReason());put(item,"containing_guard_138_raw",p.containingGuardRaw());put(item,"containing_definition_magic_38",p.containingDefinitionMagic());put(item,"native_fixed_chunk0_can_replenish",p.nativeFixedChunk0CanReplenish());put(item,"fresh_fraction_raw",p.freshFractionRaw());}return row;
    }
    public static Besieging decodeBesieging(JsonNode node){
        JsonNode normalized=normalizeBesieging(node);if(normalized.isNull())return null;ObjectNode row=object(normalized),c=object(row.get("assault_context"));
        AssaultContext context=new AssaultContext(text(c.get("status")),reason(c,"unavailable_reason",true),nb(c,"has_active_siege"),ni(c,"siege_id"),ni(c,"breach_level_raw"),ni(c,"casualty_percentage_count"),nl(c,"casualty_percentage_raw"));List<BesiegingOccurrence> values=new ArrayList<>();
        for(JsonNode raw:row.get("occurrences")){ObjectNode o=object(raw);List<BesiegingRegiment> regiments=new ArrayList<>();for(JsonNode entry:o.get("regiments")){ObjectNode r=object(entry);regiments.add(new BesiegingRegiment(i32(r.get("stored_index")),i32(r.get("army_regiment_id")),bool(r.get("available")),reason(r,"unavailable_reason",true),ni(r,"current_soldiers"),ni(r,"maximum_soldiers"),LandContextCodec.decodeData(r.get("replenishment_records_v1"))));}
            values.add(new BesiegingOccurrence(i32(o.get("stored_index")),i32(o.get("public_unit_id")),ni(o,"resolved_unit_id"),nb(o,"unit_used_fallback"),ni(o,"current_province_id"),nb(o,"current_province_used_fallback"),ni(o,"raw_unit18"),ni(o,"raw_unit170"),ni(o,"raw_unit44"),ni(o,"native_carmy_id"),nb(o,"army_used_fallback"),nb(o,"eligible"),bool(o.get("available")),reason(o,"unavailable_reason",true),ni(o,"native_whole_current_soldiers"),regiments));}
        return new Besieging(enumeration(row.get("status"),Coverage.class),reason(row,"unavailable_reason",true),i32(row.get("province_id")),ni(row,"native_province_unit_count"),ni(row,"native_besieging_strength"),bool(row.get("contributors_ready")),ni(row,"native_assault_expected_loss"),context,values);
    }
    public static JsonNode encodeBesieging(Besieging value){
        if(value==null)return NullNode.getInstance();ObjectNode row=empty().put("status",wire(value.status())).put("unavailable_reason",value.unavailableReason()).put("province_id",value.provinceId()).put("contributors_ready",value.contributorsReady());put(row,"native_province_unit_count",value.nativeProvinceUnitCount());put(row,"native_besieging_strength",value.nativeBesiegingStrength());put(row,"native_assault_expected_loss",value.nativeAssaultExpectedLoss());AssaultContext c=value.assaultContext();ObjectNode context=row.putObject("assault_context").put("status",c.status()).put("unavailable_reason",c.unavailableReason());put(context,"has_active_siege",c.hasActiveSiege());put(context,"siege_id",c.siegeId());put(context,"breach_level_raw",c.breachLevelRaw());put(context,"casualty_percentage_count",c.casualtyPercentageCount());put(context,"casualty_percentage_raw",c.casualtyPercentageRaw());
        ArrayNode occurrences=row.putArray("occurrences");for(BesiegingOccurrence o:value.occurrences()){ObjectNode out=occurrences.addObject().put("stored_index",o.storedIndex()).put("public_unit_id",o.publicUnitId()).put("available",o.available()).put("unavailable_reason",o.unavailableReason());put(out,"resolved_unit_id",o.resolvedUnitId());put(out,"unit_used_fallback",o.unitUsedFallback());put(out,"current_province_id",o.currentProvinceId());put(out,"current_province_used_fallback",o.currentProvinceUsedFallback());put(out,"raw_unit18",o.rawUnit18());put(out,"raw_unit170",o.rawUnit170());put(out,"raw_unit44",o.rawUnit44());put(out,"native_carmy_id",o.nativeCarmyId());put(out,"army_used_fallback",o.armyUsedFallback());put(out,"eligible",o.eligible());put(out,"native_whole_current_soldiers",o.nativeWholeCurrentSoldiers());ArrayNode regiments=out.putArray("regiments");for(BesiegingRegiment r:o.regiments()){ObjectNode regiment=regiments.addObject().put("stored_index",r.storedIndex()).put("army_regiment_id",r.armyRegimentId()).put("available",r.available()).put("unavailable_reason",r.unavailableReason());put(regiment,"current_soldiers",r.currentSoldiers());put(regiment,"maximum_soldiers",r.maximumSoldiers());regiment.set("replenishment_records_v1",LandContextCodec.encodeData(r.replenishmentRecords()));}}
        return row;
    }
    public static ScopedOrdered decodeScoped(JsonNode node){return scopedNormalized(normalizeScoped(node));}
    static ScopedOrdered scopedNormalized(ObjectNode row){
        var physical=physical(row);List<PhysicalPersistent> persistents=new ArrayList<>();for(int index=0;index<physical.persistents().size();index++){
            ArmySelectorModel.Persistent p=physical.persistents().get(index);ObjectNode raw=object(row.get("persistent_regiments").get(index));List<PhysicalChunk> chunks=new ArrayList<>();for(int slot=0;slot<p.chunks().size();slot++){
                ObjectNode c=object(raw.get("chunks").get(slot));chunks.add(new PhysicalChunk(p.chunks().get(slot),i32(c.get("owner_persistent_regiment_id")),ni(c,"owner_resolved_full_id"),ni(c,"origin_province_id"),ni(c,"associated_army_raw_full_id"),ni(c,"associated_army_resolved_full_id"),ni(c,"associated_unit_raw_full_id"),ni(c,"associated_unit_resolved_full_id"),reason(c,"context_unavailable_reason",false),c.has("refill_permission_switch_v1")?java.util.Optional.of(decodePermissionSwitch(c.get("refill_permission_switch_v1"),ni(c,"owner_resolved_full_id"))):java.util.Optional.empty()));}
            persistents.add(new PhysicalPersistent(p.persistentId(),p.fraction(),reason(raw,"unavailable_reason",false),chunks));}
        return new ScopedOrdered(enumeration(row.get("status"),Coverage.class),reason(row,"unavailable_reason",false),physical.subjectArmyId(),physical.subjectNativeArmyId(),physical.occurrenceCount(),physical.refreshCount(),physical.occurrences(),physical.refreshIndices(),persistents);
    }
    public static ObjectNode encodeScoped(ScopedOrdered value){
        ObjectNode row=empty().put("source","native_scoped_observed_prepared_ordered_refill").put("status",wire(value.status())).put("subject_army_id",value.subjectArmyId()).put("subject_carmy_id",value.subjectCarmyId());put(row,"unavailable_reason",value.unavailableReason());put(row,"native_persistent_occurrence_count",value.nativePersistentOccurrenceCount());put(row,"native_army_refresh_occurrence_count",value.nativeArmyRefreshOccurrenceCount());ArrayNode occurrences=row.putArray("persistent_occurrences");for(var occurrence:value.persistentOccurrences())occurrences.addObject().put("stored_index",occurrence.storedIndex()).put("persistent_regiment_id",occurrence.persistentId());ArrayNode refresh=row.putArray("army_refresh_occurrence_indices");value.armyRefreshOccurrenceIndices().forEach(refresh::add);ArrayNode persistents=row.putArray("persistent_regiments");for(PhysicalPersistent p:value.persistentRegiments()){ObjectNode out=persistents.addObject().put("persistent_regiment_id",p.persistentRegimentId());put(out,"prepared_fraction_raw",p.preparedFractionRaw());put(out,"unavailable_reason",p.unavailableReason());ArrayNode chunks=out.putArray("chunks");p.chunks().forEach(chunk->chunks.add(encodeChunk(chunk)));}return row;
    }
